import{_ as o,o as t,c as a,a2 as s}from"./chunks/framework.CqdVOxXJ.js";const e="/rakkii-cars-guide/screenshots/v2/d01-shop-board.png",n="/rakkii-cars-guide/screenshots/v2/d01b-whats-left.png",i="/rakkii-cars-guide/screenshots/v2/d02-calendar.png",d="/rakkii-cars-guide/screenshots/v2/d04b-customer-detail.png",k=JSON.parse('{"title":"Board, calendar & search","description":"","frontmatter":{},"headers":[],"relativePath":"desk/board-and-calendar.md","filePath":"desk/board-and-calendar.md","lastUpdated":1794621279000}'),c={name:"desk/board-and-calendar.md"};function l(h,r,p,g,b,m){return t(),a("div",null,[...r[0]||(r[0]=[s('<h1 id="board-calendar-search" tabindex="-1">Board, calendar &amp; search <a class="header-anchor" href="#board-calendar-search" aria-label="Permalink to &quot;Board, calendar &amp; search&quot;">​</a></h1><p><strong>Who:</strong> Owner or admin · <strong>Hub:</strong> Workshop</p><p>Four screens for seeing every car at once.</p><h2 id="shop-board" tabindex="-1">Shop board <a class="header-anchor" href="#shop-board" aria-label="Permalink to &quot;Shop board&quot;">​</a></h2><p><strong>Workshop › Shop board</strong> shows every car in play, in columns: <strong>New</strong>, <strong>Quote / LOA</strong>, <strong>Under repair</strong>, <strong>Parts &amp; QC</strong>, <strong>On hold</strong> and <strong>Ready</strong>.</p><ul><li>Filter with <strong>All</strong>, <strong>Retail</strong>, <strong>Insurance</strong> or <strong>Fleet</strong>, or <strong>Filters</strong> for more.</li><li>Press <strong>List</strong> for a table instead of columns.</li><li>Press <strong>What&#39;s left</strong> on a card to see the job&#39;s steps and what&#39;s still open. <strong>Open job</strong> takes you there.</li></ul><p><img src="'+e+'" alt="Shop board"></p><p><img src="'+n+'" alt="What&#39;s left on a board card"></p><h2 id="calendar" tabindex="-1">Calendar <a class="header-anchor" href="#calendar" aria-label="Permalink to &quot;Calendar&quot;">​</a></h2><p><strong>Workshop › Calendar</strong> lists the cars due each day (by target date or appointment). Use <strong>Today</strong> and the arrows to move between days. <strong>No target date or appointment</strong> lists open jobs with neither, so nothing is forgotten. <strong>Book this day</strong> starts a job for that day.</p><p><img src="'+i+'" alt="Calendar"></p><h2 id="customer-activity" tabindex="-1">Customer activity <a class="header-anchor" href="#customer-activity" aria-label="Permalink to &quot;Customer activity&quot;">​</a></h2><p><strong>Workshop › Customer activity</strong> shows what customers did on their pay link: approved or declined an estimate, or sent a payment proof. <strong>Unseen</strong> shows the new ones; press <strong>Mark all seen</strong> when you&#39;ve dealt with them. The bell in the top bar shows the count.</p><h2 id="job-history-and-customers" tabindex="-1">Job history and customers <a class="header-anchor" href="#job-history-and-customers" aria-label="Permalink to &quot;Job history and customers&quot;">​</a></h2><ul><li><strong>Workshop › Job history</strong>: finished jobs. Search by plate, customer or job number, and filter by date, type and status. <strong>Released · not done</strong> means the car is out but something is still open.</li><li><strong>Workshop › Customers</strong>: every customer with their cars, last visit and open jobs. Open one to see their <strong>Service history</strong>, or press <strong>New job for them</strong>.</li></ul><p><img src="'+d+'" alt="Customer page"></p><h2 id="backjobs" tabindex="-1">Backjobs <a class="header-anchor" href="#backjobs" aria-label="Permalink to &quot;Backjobs&quot;">​</a></h2><p><strong>Workshop › Backjobs</strong>: cars that came back for the same problem, grouped <strong>By responsible</strong>, with what&#39;s <strong>Still open</strong>. See <a href="/rakkii-cars-guide/reference/10-workshop-operations-board-calendar-backjobs-contractors">Board, calendar, backjobs &amp; contractors</a>.</p>',18)])])}const f=o(c,[["render",l]]);export{k as __pageData,f as default};
